window.receiveProjectSource({"path": "test/integration/event_synthesis/test_lifecycle_invalidate.py", "lines": ["\"\"\"Integration tests for the lifecycle manual-invalidate path (DAT-6167).", "", "Covers AC4 (manual invalidation via the service writes the audit row and", "updates ``last_change_id``) and AC5 (no ``merged`` state / no", "``merged_into_id``: the lifecycle module never emits that shape).", "\"\"\"", "", "from __future__ import annotations", "", "from typing import Any, Dict", "from uuid import UUID, uuid4", "", "import pytest", "from accelerate_models.event_synthesis.app.models.source_event_changes import (", "    SourceEventChange,", ")", "from accelerate_models.event_synthesis.app.models.source_events import SourceEvent", "from sqlalchemy import select", "", "from db.session_manager_async import sessionmanager_accelerate", "from microservices.event_synthesis.services.lifecycle import (", "    LifecycleEventNotFound,", "    SourceEventLifecycleService,", ")", "from test.integration.event_synthesis.helpers import seed_accelerate_source_event", "", "pytestmark = pytest.mark.integration", "", "", "async def _seed_active(", "    cleanup_ess_tables: Dict[str, list[Any]],", "    mirrored_event_type,", ") -> UUID:", "    category_id, type_id = mirrored_event_type", "    event_id = uuid4()", "    cleanup_ess_tables[\"accelerate_source_event_ids\"].append(event_id)", "    async with sessionmanager_accelerate.session() as ac:", "        await seed_accelerate_source_event(", "            ac,", "            source_event_id=event_id,", "            event_category_id=category_id,", "            event_type_id=type_id,", "        )", "    return event_id", "", "", "async def _read_event(event_id: UUID) -> SourceEvent:", "    async with sessionmanager_accelerate.session() as ac:", "        row = await ac.scalar(select(SourceEvent).where(SourceEvent.id == event_id))", "    assert row is not None", "    return row", "", "", "async def test_invalidate_event_transitions_active_row_with_audit_payload(", "    cleanup_ess_tables: Dict[str, list[Any]],", "    mirrored_event_type,", ") -> None:", "    \"\"\"AC4: status -> invalidated, change row carries actor + reason, last_change_id updated.\"\"\"", "    event_id = await _seed_active(cleanup_ess_tables, mirrored_event_type)", "", "    service = SourceEventLifecycleService()", "    transitioned = await service.invalidate_event(", "        event_id, reason=\"duplicate of upstream report\", actor=\"qa@polarisio.com\"", "    )", "    assert transitioned == 1", "", "    ev = await _read_event(event_id)", "    assert ev.status == \"invalidated\"", "", "    async with sessionmanager_accelerate.session() as ac:", "        change = (", "            (", "                await ac.execute(", "                    select(SourceEventChange)", "                    .where(SourceEventChange.event_id == event_id)", "                    .order_by(SourceEventChange.id.desc())", "                )", "            )", "            .scalars()", "            .first()", "        )", "    assert change is not None", "    assert change.change_type == \"status_changed\"", "    assert change.triggering_actor == \"qa@polarisio.com\"", "    payload = change.change_payload", "    assert payload[\"from\"] == \"active\"", "    assert payload[\"to\"] == \"invalidated\"", "    assert payload[\"reason\"] == \"duplicate of upstream report\"", "    assert payload[\"actor\"] == \"qa@polarisio.com\"", "    assert ev.last_change_id == change.id", "", "", "async def test_invalidate_event_is_idempotent_on_already_invalidated_row(", "    cleanup_ess_tables: Dict[str, list[Any]],", "    mirrored_event_type,", ") -> None:", "    \"\"\"A second call returns 0 and writes no duplicate change row.\"\"\"", "    event_id = await _seed_active(cleanup_ess_tables, mirrored_event_type)", "", "    service = SourceEventLifecycleService()", "    first = await service.invalidate_event(event_id, reason=\"r\", actor=\"qa\")", "    second = await service.invalidate_event(event_id, reason=\"r\", actor=\"qa\")", "    assert first == 1", "    assert second == 0", "", "    async with sessionmanager_accelerate.session() as ac:", "        change_count = len(", "            (", "                await ac.execute(", "                    select(SourceEventChange).where(", "                        SourceEventChange.event_id == event_id,", "                        SourceEventChange.change_type == \"status_changed\",", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "    assert change_count == 1", "", "", "async def test_invalidate_event_raises_when_missing(", "    cleanup_ess_tables: Dict[str, list[Any]],  # noqa: ARG001  (fixture for symmetry)", ") -> None:", "    \"\"\"Unknown event id -> :class:`LifecycleEventNotFound`.\"\"\"", "    service = SourceEventLifecycleService()", "    with pytest.raises(LifecycleEventNotFound):", "        await service.invalidate_event(uuid4(), reason=\"r\", actor=\"qa\")"], "blocks": [{"start": 1, "end": 29, "label": "Imports and module setup"}, {"start": 30, "end": 46, "label": "def _seed_active"}, {"start": 47, "end": 53, "label": "def _read_event"}, {"start": 54, "end": 92, "label": "def test_invalidate_event_transitions_active_row_with_audit_payload"}, {"start": 93, "end": 121, "label": "def test_invalidate_event_is_idempotent_on_already_invalidated_row"}, {"start": 122, "end": 128, "label": "def test_invalidate_event_raises_when_missing"}], "lineCount": 128, "sha256": "7f7889713b7b7213b614ed52eec6f1a3452f0c60042c56617e1ce22e25243c6f", "endsWithNewline": true});
